MAP
    NAME "SS_MAP_JURI_PREDIOS_IRREGULARES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            'ows_enable_request' '*'
            INCLUDE 'includes/common_metadata.map'
            'wfs_getfeature_formatlist' 'gml,geojson'
            'wfs_enable_request' '*'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_nodos.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_JURI_PREDIOS_IRREGULARES"
        METADATA
            'ows_title' 'Predios Irregulares'
            'ows_include_items' 'all'
            'gml_include_items' 'all'
        END #METADATA
        PROJECTION
            'init=epsg:32614'
        END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "geometry from predios_irregulares using unique gid using srid=32614"
        TYPE POLYGON
        CLASSITEM "tipo"
        CLASS
            NAME "No Capturado"
            EXPRESSION "0"
            STYLE
                COLOR 240 240 240
                OUTLINECOLOR 150 150 150
            END #STYLE
        END #CLASS
        CLASS
            NAME "Propiedades Irregulares"
            EXPRESSION "1"
            STYLE
                COLOR 235 136 113
                OUTLINECOLOR 218 37 29
            END #STYLE
        END #CLASS
        CLASS
            NAME "Afectaciones"
            EXPRESSION "2"
            STYLE
                COLOR 255 250 136
                OUTLINECOLOR 255 245 0
            END #STYLE
        END #CLASS
        CLASS
            NAME "Propiedades Regulares"
            EXPRESSION "3"
            STYLE
                COLOR 97 186 144
                OUTLINECOLOR 0 146 63
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP
